package com.retro.t9;
import java.io.*;import java.util.*;
public final class Lexicon {
 final Map<String,List<String>> exact=new HashMap<>();final Map<String,String> prefix=new HashMap<>();
 public static String digits(String word){StringBuilder b=new StringBuilder();for(char c:word.toLowerCase(Locale.ROOT).toCharArray()){if(c=='\'')continue;if(c<'a'||c>'z')return "";b.append(c<='c'?'2':c<='f'?'3':c<='i'?'4':c<='l'?'5':c<='o'?'6':c<='s'?'7':c<='v'?'8':'9');}return b.toString();}
 public static boolean valid(String s){return s!=null&&s.length()<=24&&s.matches("[a-z]+(?:'[a-z]+)*");}
 public void load(InputStream input)throws IOException{try(BufferedReader reader=new BufferedReader(new InputStreamReader(input,"UTF-8"))){String line;while((line=reader.readLine())!=null){String[] parts=line.split(" ");String word=parts[0];if(!valid(word))continue;String code=digits(word);List<String> words=exact.computeIfAbsent(code,k->new ArrayList<>());if(words.size()<24&&!words.contains(word))words.add(word);String plain=word.replace("'","");for(int i=1;i<=Math.min(6,code.length());i++)prefix.putIfAbsent(code.substring(0,i),plain.substring(0,i));}}}
 public List<String> suggest(String code,Map<String,Integer> learned){ArrayList<String> out=new ArrayList<>();ArrayList<String> personal=new ArrayList<>();for(String word:learned.keySet())if(valid(word)&&digits(word).equals(code))personal.add(word);personal.sort((a,b)->{int rank=Integer.compare(learned.get(b),learned.get(a));return rank!=0?rank:a.compareTo(b);});out.addAll(personal);List<String> base=exact.get(code);if(base!=null)for(String word:base)if(!out.contains(word)&&out.size()<12)out.add(word);String partial=prefix.get(code);if(partial!=null&&!out.contains(partial)&&out.size()<12)out.add(partial);if(out.isEmpty()){String letters="  abcdefghijklmnopqrstuvwxyz";String[] keys={"","","a","d","g","j","m","p","t","w"};StringBuilder raw=new StringBuilder();for(char c:code.toCharArray())raw.append(keys[c-'0']);out.add(raw.toString());}return out;}
}
